// Exact norm<=8 search for first-half support six with all six u entries odd.
// Mod-8 lower bound followed by exhaustive centered mod-16 lifts.
// matrix48.h generated by support_mod8_verify.py from the published candidate.
#include <immintrin.h>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#ifdef _OPENMP
#include <omp.h>
#endif
#include "matrix48.h"
using u64=unsigned long long;
static constexpr int sq16[16]={0,1,4,9,16,25,36,49,64,49,36,25,16,9,4,1};
static constexpr int sq8[8]={0,1,4,9,16,9,4,1};
struct alignas(32) Vec {__m256i x,y;};
inline Vec add8(const Vec&a,const Vec&b){return {_mm256_add_epi8(a.x,b.x),_mm256_add_epi8(a.y,b.y)};}
inline Vec from_row(int i,int coeff){
 alignas(32) uint8_t b[64]={};
 for(int j=0;j<48;j++)b[j]=(uint8_t)(coeff*A[i][j]);
 return {_mm256_load_si256((const __m256i*)b),_mm256_load_si256((const __m256i*)(b+32))};
}
inline int sum8(__m256i x){
 __m256i z=_mm256_sad_epu8(x,_mm256_setzero_si256());
 return int(_mm256_extract_epi64(z,0)+_mm256_extract_epi64(z,1)
  +_mm256_extract_epi64(z,2)+_mm256_extract_epi64(z,3));
}
inline int cost8first(const Vec&v,const __m256i&lut,const __m256i&m7){
 return sum8(_mm256_shuffle_epi8(lut,_mm256_and_si256(v.x,m7)));
}
inline int cost8second(const Vec&v,const __m256i&lut,const __m256i&m7){
 return sum8(_mm256_shuffle_epi8(lut,_mm256_and_si256(v.y,m7)));
}
struct Results {
 u64 supports=0,residue_classes=0,passes_mod8=0,lifts=0,shorts=0;
 int best_num=999999,witness[48]={};
};
int main(int argc,char**argv){
 int begin=argc>1?std::atoi(argv[1]):0,end=argc>2?std::atoi(argv[2]):43;
 if(begin<0||end>43||end<=begin)return 2;
 alignas(32) uint8_t tbl[32]={};
 for(int i=0;i<32;i++)tbl[i]=(uint8_t)sq8[i&7];
 const __m256i lut=_mm256_load_si256((const __m256i*)tbl);
 const __m256i m7=_mm256_set1_epi8(7);
 const int r[4]={1,3,5,7};
 Results total;
 #pragma omp parallel
 {
  Results z;
  #pragma omp for schedule(dynamic,1)
  for(int i=begin;i<end;i++){
   for(int j=i+1;j<44;j++)for(int k=j+1;k<45;k++)
   for(int l=k+1;l<46;l++)for(int m=l+1;m<47;m++)for(int n=m+1;n<48;n++){
    ++z.supports;
    Vec term[6][4];int ids[6]={i,j,k,l,m,n};
    for(int t=0;t<6;t++)for(int q=0;q<4;q++)term[t][q]=from_row(ids[t],r[q]);
    Vec pairs[64],triples[64];int minp[64],mint[64];
    for(int p=0;p<64;p++){
     int a=p>>4,b=(p>>2)&3,c=p&3;
     pairs[p]=add8(add8(term[0][a],term[1][b]),term[2][c]);
     minp[p]=r[a]*r[a]+sq8[r[b]]+sq8[r[c]];
    }
    for(int t=0;t<64;t++){
     int d=t>>4,e=(t>>2)&3,f=t&3;
     triples[t]=add8(add8(term[3][d],term[4][e]),term[5][f]);
     mint[t]=sq8[r[d]]+sq8[r[e]]+sq8[r[f]];
    }
    for(int p=0;p<64;p++)for(int t=0;t<64;t++){
     ++z.residue_classes;
     int lower=minp[p]+mint[t];
     Vec v=add8(pairs[p],triples[t]);
     lower+=cost8first(v,lut,m7);
     if(lower>128)continue;
     lower+=cost8second(v,lut,m7);
     if(lower>128)continue;
     ++z.passes_mod8;
     int ind[6]={p>>4,(p>>2)&3,p&3,t>>4,(t>>2)&3,t&3};
     int u[6]={r[ind[0]],0,0,0,0,0};
     for(int mask=0;mask<32;mask++){
      for(int s=1;s<6;s++)u[s]=r[ind[s]]-(((mask>>(s-1))&1)?8:0);
      int norm=0;for(int s=0;s<6;s++)norm+=u[s]*u[s];
      if(norm+6>128)continue; // all six u positions are odd; so are six v positions
      ++z.lifts;
      for(int col=0;col<48&&norm<=128;col++){
       int sum=0;for(int s=0;s<6;s++)sum+=u[s]*A[ids[s]][col];
       norm+=sq16[(unsigned)sum&15];
      }
      if(norm<=128){
       ++z.shorts;
       if(norm<z.best_num){
        z.best_num=norm;std::memset(z.witness,0,sizeof(z.witness));
        for(int s=0;s<6;s++)z.witness[ids[s]]=u[s];
        #pragma omp critical
        {
         std::printf("WITNESS numerator=%d support=%d,%d,%d,%d,%d,%d u=%d,%d,%d,%d,%d,%d\n",norm,i,j,k,l,m,n,u[0],u[1],u[2],u[3],u[4],u[5]);
         std::fflush(stdout);
        }
       }
      }
     }
    }
   }
  }
  #pragma omp critical
  {
   total.supports+=z.supports;total.residue_classes+=z.residue_classes;
   total.passes_mod8+=z.passes_mod8;total.lifts+=z.lifts;total.shorts+=z.shorts;
   if(z.best_num<total.best_num){
    total.best_num=z.best_num;std::memcpy(total.witness,z.witness,sizeof(z.witness));
   }
  }
 }
 std::printf("SUMMARY first=[%d,%d) supports=%llu mod8_classes=%llu pass_mod8=%llu lifts=%llu shorts=%llu best_num=%d\n",
 begin,end,total.supports,total.residue_classes,total.passes_mod8,total.lifts,total.shorts,total.best_num);
 if(total.shorts){
  std::printf("WITNESS_U ");
  for(int i=0;i<48;i++)std::printf("%d%c",total.witness[i],i==47?'\n':' ');
 }
 return total.shorts?3:0;
}
